Rules.InvariantScript:
Clear(colVacationsUpdates);
Set(varFilterEmployee, "");
Set(varFilterFrom, Blank());
Set(varFilterTo, Blank());
Reset(txt_FilterEmployee);
Reset(DatePicker_FilterFrom);
Reset(DatePicker_FilterTo);
Select(btn_ReloadApprovals);

Set(varFilterEmployee, "");
Set(varFilterFrom, Blank());
Set(varFilterTo, Blank());
Reset(txt_FilterEmployee);
Reset(DatePicker_FilterFrom);
Reset(DatePicker_FilterTo);

Refresh('Vacations Tracking (Days)');
If(
    varIsAdmin,
    ClearCollect(colApprovalsSource, 'Vacations Tracking (Days)'),
    ClearCollect(
        colApprovalsSource,
        Filter('Vacations Tracking (Days)', ApproverID_1 = User().Email)
    )
);

If(
    CountRows(colVacationsUpdates) = 0,
    Notify("No changes to save", NotificationType.Information),
    Set(varIsSaving, true);
    Patch(
        'Vacations Tracking (Days)',
        ShowColumns(
            colVacationsUpdates,
            ID,
            Type_of_leave,
            ApprovalStatus_1,
            ApprovalStatus_2,
            Approver_Comments
        )
    );
    ForAll(
        colVacationsUpdates As u,
        If(
            u.ApprovalStatus_1 = "Approved" || u.ApprovalStatus_1 = "Rejected",
            With(
                {
                    hoursRows: Filter(
                        Filter(
                            'Hours Tracking (Hours)',
                            Employee = u.Employee &&
                            Date >= u.StartDate &&
                            Date <= u.EndDate
                        ),
                        StartsWith(LOG_ID, u.LOG_ID & "_")
                    )
                },
                If(
                    CountRows(hoursRows) > 0,
                    Patch(
                        'Hours Tracking (Hours)',
                        ForAll(
                            hoursRows As h,
                            {
                                ID: h.ID,
                                ApprovalStatus_1: u.ApprovalStatus_1,
                                Approver_Comments: u.Approver_Comments
                            }
                        )
                    )
                );
                Office365Outlook.SendEmailV2(
                    u.Employee,
                    Text(u.TypeofLeave) & " Request " & Text(u.ApprovalStatus_1),
                    "Your " & Text(u.TypeofLeave) & " request has been " & Text(u.ApprovalStatus_1) & ".<br><br>" &
                    "<b>Type:</b> " & Text(u.TypeofLeave) & "<br>" &
                    "<b>Dates:</b> " & Text(u.StartDate, "dd-mmm-yyyy") & " to " & Text(u.EndDate, "dd-mmm-yyyy") & "<br>" &
                    "<b>Comments:</b> " & Text(u.Approver_Comments),
                    {
                        Cc: u.ApproverID_1,
                        IsHtml: true
                    }
                )
            )
        )
    );
    Clear(colVacationsUpdates);
    Notify("Approvals saved", NotificationType.Success);
    Select(btn_ReloadApprovals);
    Set(varIsSaving, false)
)
